      },
      {
        "name": "항법 솔루션",
        "desc": "계열사를 통해 방위·우주항공용 항법 기술을 공급합니다."
      },
      {
        "name": "고압 용기",
        "desc": "특수·수소 가스의 운송·저장용 용기를 공급합니다."
      }
    ],
